//! Compatibility tests against the fixtures generated by the Go implementation.

mod common;

use std::net::IpAddr;

use hickory_proto::op::{Message, MessageType, OpCode, Query as HQuery};
use hickory_proto::rr::{DNSClass, Name, RData, Record, RecordType};
use pm_config::Config;
use pm_nameserver::responder::{
    make_message_record, Level, Responder, StaticResponder,
};
use pm_nameserver::{parse_listen_addresses, register_options};
use serde_json::Value;

fn fixture(name: &str) -> Value {
    let path = format!("{}/../fixtures/m0/{name}", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn go_json(value: &Value) -> String {
    String::from_utf8(pm_dsd::gojson::to_vec(value).unwrap()).unwrap()
}

#[test]
fn listen_address_option_matches_go_export() {
    let expected = fixture("nameserver_options.json");
    let expected = expected.as_array().unwrap();
    assert_eq!(expected.len(), 1);

    let config = Config::new();
    register_options(&config, "localhost:53").unwrap();
    let ours: Vec<_> = config
        .export_options()
        .into_iter()
        .filter(|o| o.key == "dns/listenAddress")
        .collect();
    assert_eq!(ours.len(), 1);
    assert_eq!(
        go_json(&serde_json::to_value(&ours[0]).unwrap()),
        go_json(&expected[0])
    );
}

#[test]
fn listen_address_option_validates_like_go() {
    let config = Config::new();
    register_options(&config, "localhost:53").unwrap();
    for ok in ["localhost:53", "127.0.0.1:5353", "[::1]:53", "0.0.0.0:53"] {
        assert!(
            config
                .set_config_option("dns/listenAddress", serde_json::json!(ok))
                .is_ok(),
            "{ok}"
        );
    }
    for bad in ["example.com:53", "localhost", "127.0.0.1", "::1:53", "localhost:123456"] {
        assert!(
            config
                .set_config_option("dns/listenAddress", serde_json::json!(bad))
                .is_err(),
            "{bad}"
        );
    }
}

#[test]
fn flag_address_is_the_option_default() {
    let config = Config::new();
    register_options(&config, "127.0.0.1:5353").unwrap();
    let get = config.get_as_string("dns/listenAddress", "x");
    assert_eq!(get(), "127.0.0.1:5353");
    config
        .set_config_option("dns/listenAddress", serde_json::json!("127.0.0.1:5454"))
        .unwrap();
    assert_eq!(get(), "127.0.0.1:5454");
}

#[test]
fn listen_addresses_match_go() {
    let fixture = fixture("nameserver.json");
    for case in fixture["listen_addresses"].as_array().unwrap() {
        let input = case["input"].as_str().unwrap();
        // The generator ran with an IPv6 stack; Go only adds ::1 then.
        let parsed = parse_listen_addresses(input, true);
        if case["error"].as_bool().unwrap() {
            assert!(parsed.is_err(), "{input}");
            continue;
        }
        let parsed = parsed.unwrap_or_else(|e| panic!("{input}: {e}"));
        assert_eq!(parsed.ip1.to_string(), case["ip1"].as_str().unwrap(), "{input}");
        assert_eq!(
            parsed.ip2.map(|ip| ip.to_string()),
            case["ip2"].as_str().map(str::to_string),
            "{input}"
        );
        assert_eq!(u64::from(parsed.port), case["port"].as_u64().unwrap(), "{input}");
    }

    // Without an IPv6 stack, localhost has only the IPv4 listener.
    let parsed = parse_listen_addresses("localhost:53", false).unwrap();
    assert_eq!(parsed.ip1, "127.0.0.17".parse::<IpAddr>().unwrap());
    assert!(parsed.ip2.is_none());
}

fn request(name: &str, qtype: u16, extra_question: bool) -> Message {
    let mut msg = Message::new(4711, MessageType::Query, OpCode::Query);
    msg.metadata.recursion_desired = true;
    msg.add_query(HQuery::query(
        Name::from_ascii(name).unwrap(),
        RecordType::from(qtype),
    ));
    if extra_question {
        msg.id_fix();
    }
    msg
}

trait IdFix {
    fn id_fix(&mut self);
}

impl IdFix for Message {
    fn id_fix(&mut self) {
        self.metadata.id = 7;
        let mut second = HQuery::query(Name::from_ascii("example.org.").unwrap(), RecordType::AAAA);
        second.set_query_class(DNSClass::IN);
        self.add_query(second);
    }
}

fn record_ip(record: &Record) -> String {
    match &record.data {
        RData::A(a) => a.0.to_string(),
        RData::AAAA(a) => a.0.to_string(),
        other => panic!("unexpected {other:?}"),
    }
}

fn responder_by_name(name: &str) -> StaticResponder {
    match name {
        "block_ip" => StaticResponder::block_ip(&["blocked by test"]),
        "zero_ip" => StaticResponder::zero_ip(&["zero"]),
        "localhost" => StaticResponder::localhost(&[] as &[&str]),
        "nxdomain" => StaticResponder::nx_domain(&["nxdomain: no such thing"]),
        "refused" => StaticResponder::refused(&["unsupported qclass"]),
        "server_failure" => StaticResponder::server_failure(&["internal error: ", "second message"]),
        other => panic!("unknown responder {other}"),
    }
}

#[tokio::test(start_paused = true)]
async fn responders_match_go() {
    let fixture = fixture("nameserver.json");
    let cases = fixture["responders"].as_array().unwrap();
    assert!(cases.len() > 30);
    for case in cases {
        let name = case["responder"].as_str().unwrap();
        let qname = case["qname"].as_str().unwrap();
        let qtype = case["qtype"].as_u64().unwrap() as u16;
        let multi = qname.contains('+');
        let msg = if multi {
            request("example.com.", 1, true)
        } else {
            request(qname, qtype, false)
        };
        let responder = if multi {
            StaticResponder::block_ip::<&str>(&[])
        } else {
            responder_by_name(name)
        };
        let reply = responder.reply(&msg).await.unwrap();
        let want = &case["reply"];
        let ctx = format!("{name} {qname} {qtype}");

        assert_eq!(want["nil"].as_bool(), Some(false), "{ctx}");
        assert_eq!(u64::from(reply.metadata.id), want["id"].as_u64().unwrap(), "{ctx}");
        assert_eq!(reply.metadata.message_type, MessageType::Response, "{ctx}");
        assert_eq!(reply.metadata.recursion_desired, want["rd"].as_bool().unwrap(), "{ctx}");
        assert_eq!(
            reply.metadata.recursion_available,
            want["ra"].as_bool().unwrap(),
            "{ctx}"
        );
        assert_eq!(
            u64::from(u16::from(reply.metadata.response_code)),
            want["rcode"].as_u64().unwrap(),
            "{ctx}"
        );

        let q = want["question"].as_array().unwrap();
        assert_eq!(reply.queries.len(), q.len(), "{ctx}");
        assert_eq!(reply.queries[0].name().to_ascii(), q[0]["name"].as_str().unwrap(), "{ctx}");

        let answers = want["answer"].as_array().unwrap();
        assert_eq!(reply.answers.len(), answers.len(), "{ctx}");
        for (got, want) in reply.answers.iter().zip(answers) {
            assert_eq!(got.name.to_ascii(), want["name"].as_str().unwrap(), "{ctx}");
            assert_eq!(u64::from(got.ttl), want["ttl"].as_u64().unwrap(), "{ctx}");
            let text = want["text"].as_str().unwrap();
            assert!(text.ends_with(&record_ip(got)), "{ctx}: {text}");
        }

        let extras = want["extra"].as_array().unwrap();
        assert_eq!(reply.additionals.len(), extras.len(), "{ctx}");
        for (got, want) in reply.additionals.iter().zip(extras) {
            assert_eq!(got.name.to_ascii(), want["name"].as_str().unwrap(), "{ctx}");
            assert_eq!(u64::from(got.ttl), want["ttl"].as_u64().unwrap(), "{ctx}");
            let RData::TXT(txt) = &got.data else {
                panic!("{ctx}: not TXT");
            };
            let strings: Vec<String> = txt
                .txt_data
                .iter()
                .map(|d| String::from_utf8_lossy(d).into_owned())
                .collect();
            let want_strings: Vec<String> = want["txt"]
                .as_array()
                .unwrap()
                .iter()
                .map(|s| s.as_str().unwrap().to_string())
                .collect();
            assert_eq!(strings, want_strings, "{ctx}");
        }
    }
}

#[test]
fn message_records_match_go() {
    let fixture = fixture("nameserver.json");
    for case in fixture["message_records"].as_array().unwrap() {
        let level = match case["level"].as_str().unwrap() {
            "INF" => Level::Info,
            "ERR" => Level::Error,
            other => panic!("level {other}"),
        };
        let msg = case["msg"].as_str().unwrap();
        let got = make_message_record(level, msg);
        if case["error"].as_bool().unwrap() {
            assert!(got.is_err(), "{msg:?} should fail");
            continue;
        }
        let record = got.unwrap_or_else(|e| panic!("{msg:?}: {e}"));
        let want = &case["rr"];
        assert_eq!(record.name.to_ascii(), want["name"].as_str().unwrap(), "{msg:?}");
        assert_eq!(u64::from(record.ttl), want["ttl"].as_u64().unwrap());
        let RData::TXT(txt) = &record.data else {
            panic!("not TXT");
        };
        // Compare the wire form of the rdata, which is what clients receive.
        let mut rdata = Vec::new();
        for string in txt.txt_data.iter() {
            rdata.push(string.len() as u8);
            rdata.extend_from_slice(string);
        }
        let hex: String = rdata.iter().map(|b| format!("{b:02x}")).collect();
        assert_eq!(hex, case["rdata_hex"].as_str().unwrap(), "{msg:?}");
    }
}
